(function(){
"use strict";
const landing=document.getElementById("landing-page"),auth=document.getElementById("auth-page"),workspace=document.getElementById("workspace"),modal=document.getElementById("modal-root"),toastBox=document.getElementById("toast-region");
const S={page:"landing",mode:"login",view:"overview",data:null,joinPreview:null,chatGroupId:"",chatScrollRestore:null,busy:false,supabaseAuth:false,authClient:null,authNotice:"",communityFilters:{q:"",min:"",max:"",frequency:"",seats:"",turns:"",sort:"newest"},activityFilters:{q:"",category:"",direction:"",status:"",from:"",to:"",min:"",max:""}};
const icon={overview:"▦",groups:"♧",chats:"▤",wallet:"◉",community:"◎",trust:"✓",activity:"⌁",settings:"⚙"};
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function cash(v){return new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(v||0));}
function date(v){const d=new Date(v);return !v||isNaN(d)?"Date to be agreed":new Intl.DateTimeFormat("en-NG",{day:"numeric",month:"short"}).format(d);}
function messageTime(v){const d=new Date(v);return !v||isNaN(d)?"":new Intl.DateTimeFormat("en-NG",{hour:"numeric",minute:"2-digit"}).format(d);}
function dueNow(v){return String(v||"").slice(0,10)<=new Date().toISOString().slice(0,10);}
function preferredWorkspaceView(){const postId=new URLSearchParams(location.search).get("post"),offer=(S.data?.publicOffers||[]).find(item=>item.id===postId);if(offer){S.communityFilters.q=offer.name;return"community";}return"overview";}
function initials(v){return String(v||"TA").trim().split(/\s+/).slice(0,2).map(x=>x[0]||"").join("").toUpperCase();}
function theme(v){document.documentElement.dataset.theme="light";}
function page(v){S.page=v;landing.classList.toggle("hidden",v!=="landing");auth.classList.toggle("hidden",v!=="auth");workspace.classList.toggle("hidden",v!=="app");window.scrollTo(0,0);}
async function api(url,method,body){const o={method:method||"GET",credentials:"same-origin",headers:{}};if(body!==undefined){o.headers["Content-Type"]="application/json";o.body=JSON.stringify(body);}if(S.authClient){const {data}=await S.authClient.auth.getSession();if(data.session?.access_token)o.headers.Authorization="Bearer "+data.session.access_token;}if(!Object.keys(o.headers).length)delete o.headers;const r=await fetch(url,o);let j={};try{j=await r.json();}catch(e){}if(!r.ok)throw new Error(j.error||"Something went wrong.");return j;}
function toast(s,error){toastBox.innerHTML="<div class='toast "+(error?"toast-error":"")+"'><i></i><span>"+esc(s)+"</span><button data-action='toast-close'>×</button></div>";clearTimeout(toast.t);toast.t=setTimeout(()=>toastBox.innerHTML="",4200);}
function showAuth(mode){S.mode=mode;S.authNotice="";page("auth");renderAuth();}
function renderAuth(){
 const signup=S.mode==="signup";
 auth.innerHTML="<div class='auth-shell'><aside class='auth-aside'><button class='brand auth-brand' data-action='home'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Ajo group records</small></span></button><div class='auth-quote'><span class='quote-mark'>“</span><h1>Good Ajo groups start with clear terms.</h1><p>Review group terms, contribution entries, and the agreed payout order in one place.</p><div class='auth-mini-stat'><b>TA</b><span><strong>Ajo group records.</strong><small>Trust Ajo · community savings</small></span></div></div><small class='auth-aside-foot'>Ajo group records</small></aside><section class='auth-panel'><div class='auth-top'><button class='text-link' data-action='home'>← Back to home</button><span>"+(signup?"Already have an account?":"New to Trust Ajo?")+" <button class='inline-link' data-action='"+(signup?"login":"signup")+"'>"+(signup?"Sign in":"Create an account")+"</button></span></div><div class='auth-form-wrap'><small class='section-kicker'>WELCOME TO TRUST AJO</small><h2>"+(signup?"Create your space.":"Good to see you again.")+"</h2><p class='auth-subtitle'>"+(signup?"Create an account to find and review Ajo groups.":"Sign in to see your Ajo groups and contribution records.")+"</p>"+
 (signup?"<form data-form='register' class='auth-form'><label>Full name<input name='name' required minlength='2' placeholder='e.g. Adaeze Okafor'></label><label>Email address<input name='email' type='email' required placeholder='you@example.com'></label><label>Password<input type='password' name='password' required minlength='8' placeholder='At least 8 characters'></label><button class='btn btn-primary btn-full btn-lg' type='submit'>Create account</button><p class='form-note'>No real identity numbers, bank details, or funds are needed.</p></form>":"<form data-form='login' class='auth-form'><label>Email address<input name='email' type='email' required placeholder='you@example.com'></label><label>Password<input type='password' name='password' required placeholder='Your password'></label><button class='btn btn-primary btn-full btn-lg' type='submit'>Sign in</button></form><div class='auth-divider'>OR USE SAMPLE DATA</div><button class='btn btn-sample btn-full' data-action='sample-workspace'> &nbsp; Enter sample workspace</button><p class='form-note'>Synthetic activity only. No real payment or identity checks happen.</p>")+
 "<p class='auth-bottom'>Group terms · Member-visible records <button data-action='help'>About Trust Ajo</button></p></div></section></div>";
 if(S.supabaseAuth){auth.querySelector(".auth-divider")?.remove();const sample=auth.querySelector("[data-action='sample-workspace']");if(sample){sample.nextElementSibling?.remove();sample.remove();}}
 if(S.authNotice)auth.querySelector(".auth-subtitle")?.insertAdjacentHTML("afterend","<p class='form-note' role='status'>"+esc(S.authNotice)+"</p>");
}
function nav(id,label){return"<button class='side-link "+(S.view===id?"active":"")+"' data-view='"+id+"'>"+label+"</button>";}
function heading(){return({overview:"Your overview",groups:"Ajo groups",chats:"Group chats",wallet:"Wallet",community:"Community",trust:"Trust & verification",activity:"Wallet activity",settings:"Settings"})[S.view]||"Your overview";}
function groupCard(g){
 const pct=g.memberCount?Math.round(g.paidThisCycle/g.memberCount*100):0;
 const action="<button class='btn btn-outline btn-small' data-action='details' data-id='"+esc(g.id)+"'>Open group space</button>";
 return"<article class='group-card'><div class='group-top'><span class='cycle-tag'>"+esc(g.frequency)+" Ajo group · "+esc(g.status||"active")+"</span></div><h3>"+esc(g.name)+"</h3><p>"+g.memberCount+" members · private group discussion</p><div class='group-money'><div><small>CONTRIBUTION</small><strong>"+cash(g.contributionAmount)+"</strong><i>per "+esc(g.frequency.toLowerCase())+" cycle</i></div><div class='member-count'><strong>"+g.memberCount+"<small>/"+g.capacity+"</small></strong><i>members</i></div></div><div class='progress-caption'><span>Sample cycle entries</span><b>"+g.paidThisCycle+" of "+g.memberCount+" recorded</b></div><div class='progress'><span style='width:"+pct+"%'></span></div><div class='group-foot'><span>Next due "+date(g.nextDueAt)+"</span><span>Sample data</span></div><div class='group-actions'>"+action+"<button class='btn btn-outline btn-small' data-action='group-chat-open' data-id='"+esc(g.id)+"'>Open group chat</button></div></article>";
}
function card(label,value,note){return"<article class='metric-card'><small>"+label+"</small><strong>"+value+"</strong><p>"+note+"</p></article>";}
function overview(){
 const d=S.data,groups=d.groups||[],first=(d.user.name||"there").split(" ")[0],next=groups.slice().sort((a,b)=>new Date(a.nextDueAt)-new Date(b.nextDueAt))[0];
 const groupContent=groups.length?groups.slice(0,2).map(groupCard).join(""):"<div class='empty'><b>Your first Ajo group starts here.</b><p>Create an Ajo group or join one using an invite code.</p></div>";
 return "<div class='welcome-row'><div><small class='section-kicker'>YOUR AJO COMMUNITY</small><h1>Welcome back, "+esc(first)+".</h1><p>Find people to save with, manage your wallet, and coordinate in private Ajo groups.</p></div><button class='btn btn-primary' data-action='new-group'>Create an Ajo group</button></div><section class='overview-hero'><div><span class='hero-kicker'>WALLET + COMMUNITY</span><h2>Find your people.<br><em>Keep every term clear.</em></h2><p>Search offers by amount and cadence, then agree the details in a private group space.</p><button class='btn btn-light' data-view='community'>Explore community offers</button></div></section><div class='metrics-grid'>"+card("WALLET BALANCE",cash(d.wallet?.balance||0),"Sample balance · no real funds")+card("AJO GROUPS",String(groups.length),"Groups you belong to")+card("NEXT DUE DATE",next?date(next.nextDueAt):"—",next?esc(next.name):"No upcoming Ajo")+card("CURRENT CYCLE ENTRIES",String(groups.reduce((sum,g)=>sum+(Number(g.paidThisCycle)||0),0)),"Sample records")+"</div><section class='panel main-panel'><div class='panel-head'><div><small class='section-kicker'>YOUR AJO GROUPS</small><h2>Your groups</h2></div><button class='text-link' data-view='wallet'>Open wallet</button></div><div class='group-stack'>"+groupContent+"</div></section>";
}
function groupsPage(){
 const gs=S.data.groups||[],preview=S.joinPreview;
 const previewCard=preview?"<section class='join-preview panel' aria-live='polite'><small class='section-kicker'>REVIEW BEFORE JOINING</small><h2>"+esc(preview.group.name)+"</h2><div class='join-terms'><div><small>CONTRIBUTION</small><b>"+cash(preview.group.contributionAmount)+" / "+esc(preview.group.frequency.toLowerCase())+"</b></div><div><small>NEXT DUE</small><b>"+date(preview.group.nextDueAt)+"</b></div><div><small>MEMBERS</small><b>"+preview.group.memberCount+" / "+preview.group.capacity+"</b></div></div><div class='join-rotation'><small>AGREED PAYOUT ORDER</small><b>"+esc((preview.group.payoutOrder||[]).join(" · "))+"</b></div><p class='cycle-start-note'>Review the group terms and scheduled commitment before joining.</p>"+(preview.conflict?"<p class='join-conflict' role='status'>Schedule conflict: this Ajo group overlaps "+esc(preview.conflict.groupName)+" on "+date(preview.conflict.date)+". Ask the organizer to agree a different date first.</p>":"<p class='join-clear'>No same-day due-date clash found in the next 90 days.</p>")+"<div class='modal-actions'><button class='btn btn-quiet' data-action='dismiss-join-preview'>Cancel</button><button class='btn btn-primary' data-action='confirm-join' "+(preview.conflict?"disabled":"")+">I agree, join this group</button></div></section>":"";
 const modeNote="Prototype: wallet debits and Ajo payouts use sample balances. No real money moves.";
 return "<div class='page-head'><div><small class='section-kicker'>PRIVATE GROUPS</small><h1>Your Ajo groups</h1><p>Review group terms, wallet contribution schedule, payout order, and private chat.</p></div><button class='btn btn-primary' data-action='new-group'>Create Ajo group</button></div><div class='notice'><span>"+modeNote+"</span></div><section class='panel join-panel'><div><small class='section-kicker'>JOIN BY INVITE</small><h2>Review group terms</h2><p>Enter a private invite code to see the amount, schedule, capacity, and payout order before joining.</p></div><form data-form='join-group' class='join-form'><label for='join-code'>Invite code</label><div><input id='join-code' name='joinCode' required minlength='8' maxlength='16' autocomplete='off' autocapitalize='characters' placeholder='Enter invite code'><button class='btn btn-outline' type='submit'>Review terms</button></div></form></section>"+previewCard+"<div class='group-grid'>"+(gs.length?gs.map(groupCard).join(""):"<div class='empty'><b>No Ajo groups yet</b><p>Post or join an offer in Community, or create a group directly.</p></div>")+"</div><details class='panel test-cases'><summary>Prototype guide</summary><p>Use sample data only. Wallet debits and payout credits are simulated; no funds move.</p><ol><li>Create a group and invite others with its private code.</li><li>Join a public offer through Community and open the private group chat.</li><li>Request a payout swap and ask the receiving member to accept.</li><li>Simulate a contribution from the wallet on the due date.</li><li>After a full payout rotation, members record whether to continue, recruit replacements, or leave.</li></ol></details>";
}

function chatsPage(){
 const groups=S.data.groups||[];if(!groups.length)return"<div class='page-head'><div><small class='section-kicker'>PRIVATE GROUP SPACES</small><h1>Group chats</h1><p>Each Ajo group has its own member-only conversation.</p></div></div><div class='empty'><b>No group chats yet.</b><p>Join or create an Ajo group to open its private chat.</p></div>";
 const current=groups.find(g=>g.id===S.chatGroupId)||groups[0];S.chatGroupId=current.id;
 const tabs=groups.map(g=>{const last=(g.chat||[]).at(-1);return"<button role='tab' aria-selected='"+(g.id===current.id)+"' class='chat-tab "+(g.id===current.id?"active":"")+"' data-action='select-chat-group' data-id='"+esc(g.id)+"'><span class='chat-tab-avatar'>"+esc(initials(g.name))+"</span><span class='chat-tab-copy'><b>"+esc(g.name)+"</b><small>"+(last?esc(last.text):esc(g.frequency)+" · "+g.memberCount+" members")+"</small></span>"+(last?"<time>"+messageTime(last.createdAt)+"</time>":"")+"</button>";}).join("");
 const messages=(current.chat||[]).map(m=>"<article class='chat-bubble "+(m.userId===S.data.user.id?"chat-bubble-mine":"chat-bubble-theirs")+"'><b>"+esc(m.name)+(m.userId===S.data.user.id?" · you":"")+"</b><p>"+esc(m.text)+"</p><time title='"+esc(new Date(m.createdAt).toLocaleString())+"'>"+messageTime(m.createdAt)+"</time></article>").join("");
 return"<div class='page-head'><div><small class='section-kicker'>PRIVATE GROUP SPACES</small><h1>Group chats</h1><p>Choose an Ajo group to open its member-only conversation.</p></div></div><div class='whatsapp-layout'><aside class='chat-list' aria-label='Ajo conversations'><div class='chat-list-heading'><b>Your Ajo chats</b><small>"+groups.length+" groups</small></div><div class='chat-tabs' role='tablist' aria-label='Ajo group conversations'>"+tabs+"</div></aside><section class='panel group-chat-panel' role='tabpanel'><header class='whatsapp-chat-header'><span class='chat-tab-avatar'>"+esc(initials(current.name))+"</span><div><b>"+esc(current.name)+"</b><small>"+current.memberCount+" members · private group chat</small></div><button class='btn btn-outline btn-small' data-action='details' data-id='"+esc(current.id)+"'>Group details</button></header><div class='group-chat-thread' aria-live='polite'>"+(messages||"<div class='chat-empty'><b>No messages yet</b><span>Start the conversation with your Ajo group.</span></div>")+"</div><form data-form='group-chat' class='chat-composer'><input type='hidden' name='groupId' value='"+esc(current.id)+"'><label class='sr-only' for='chat-message-input'>Message to "+esc(current.name)+"</label><input id='chat-message-input' name='text' maxlength='500' required autocomplete='off' placeholder='Type a message'><button class='chat-send' aria-label='Send message'>➤</button></form></section></div><p class='chat-safety-note'>Sample chat only. Do not post identity numbers, bank details, or private financial information.</p>";
}
function activityPage(){
 const all=S.data.activity||[],f=S.activityFilters,categories=[...new Set(all.map(a=>a.category).filter(Boolean))],statuses=[...new Set(all.map(a=>a.status).filter(Boolean))];
 const rows=all.filter(a=>{const text=(a.title+" "+(a.reference||"")+" "+a.category).toLowerCase(),day=String(a.createdAt||"").slice(0,10),amount=Number(a.amount)||0;return(!f.q||text.includes(f.q.toLowerCase()))&&(!f.category||a.category===f.category)&&(!f.direction||a.direction===f.direction)&&(!f.status||a.status===f.status)&&(!f.from||day>=f.from)&&(!f.to||day<=f.to)&&(f.min===""||amount>=Number(f.min))&&(f.max===""||amount<=Number(f.max));});
 return"<div class='page-head'><div><small class='section-kicker'>ACCOUNT ACTIVITY</small><h1>Recorded activity</h1><p>Find sample entries by type, date, amount, or reference.</p></div><button class='btn btn-outline' data-action='refresh'>Refresh</button></div><div class='notice'><span>Sample records only. Wallet events also appear in the Wallet ledger.</span></div><section class='panel table-panel'><div class='panel-head'><div><small class='section-kicker'>RECENT ENTRIES</small><h2>Activity history</h2></div><small>"+rows.length+" of "+all.length+" items</small></div><form data-form='activity-filter' class='activity-filters'><label>Search<input name='q' value='"+esc(f.q)+"' placeholder='Entry or reference'></label><label>Category<select name='category'><option value=''>All categories</option>"+categories.map(x=>"<option value='"+esc(x)+"' "+(f.category===x?"selected":"")+">"+esc(x)+"</option>").join("")+"</select></label><label>Direction<select name='direction'><option value=''>In and out</option><option value='in' "+(f.direction==="in"?"selected":"")+">Money in</option><option value='out' "+(f.direction==="out"?"selected":"")+">Money out</option></select></label><label>Record type<select name='status'><option value=''>All types</option>"+statuses.map(x=>"<option value='"+esc(x)+"' "+(f.status===x?"selected":"")+">"+esc(x.replaceAll("_"," "))+"</option>").join("")+"</select></label><label>From<input type='date' name='from' value='"+esc(f.from)+"'></label><label>To<input type='date' name='to' value='"+esc(f.to)+"'></label><label>Minimum amount<input type='number' min='0' name='min' value='"+esc(f.min)+"' placeholder='₦0'></label><label>Maximum amount<input type='number' min='0' name='max' value='"+esc(f.max)+"' placeholder='Any'></label><button class='btn btn-primary' type='submit'>Apply filters</button><button class='btn btn-quiet' type='button' data-action='activity-clear'>Clear</button></form>"+(rows.length?"<div class='table-scroll'><table><thead><tr><th>ENTRY</th><th>CATEGORY</th><th>REFERENCE</th><th>DATE</th><th>AMOUNT</th><th>RECORD TYPE</th></tr></thead><tbody>"+rows.map(a=>"<tr><td><b>"+esc(a.title)+"</b></td><td>"+esc(a.category)+"</td><td class='mono'>"+esc(a.reference||"—")+"</td><td>"+date(a.createdAt)+"</td><td>"+(a.direction==="out"?"−":"+")+cash(a.amount)+"</td><td><span class='table-status'>"+esc(String(a.status||"sample").replaceAll("_"," "))+"</span></td></tr>").join("")+"</tbody></table></div>":"<div class='empty'><b>No entries match these filters.</b><p>Change or clear your filters to see more activity.</p></div>")+"</section>";
}
function walletPage(){
 const w=S.data.wallet||{balance:0,transactions:[]};
 return "<div class='page-head'><div><small class='section-kicker'>SAMPLE WALLET</small><h1>Your wallet</h1><p>Contribution debits and Ajo payouts are shown here using sample data.</p></div></div><div class='notice'><span>Prototype only: no funds are held or transferred. Fee bands are illustrative.</span></div><section class='wallet-hero panel'><div><small>AVAILABLE SAMPLE BALANCE</small><strong>"+cash(w.balance)+"</strong><span>Sample data · no real money</span></div><div class='wallet-actions'><button class='btn btn-light' data-action='wallet-deposit'>＋ Add funds</button><button class='btn btn-outline' data-action='wallet-withdraw'>Withdraw</button></div></section><div class='wallet-layout'><section class='panel table-panel'><div class='panel-head'><div><small class='section-kicker'>WALLET LEDGER</small><h2>Recent activity</h2></div><small>"+(w.transactions||[]).length+" items</small></div>"+((w.transactions||[]).length?"<div class='table-scroll'><table><thead><tr><th>ACTIVITY</th><th>DATE</th><th>AMOUNT</th><th>FEE</th><th>TYPE</th></tr></thead><tbody>"+w.transactions.map(x=>"<tr><td><b>"+esc(x.title)+"</b></td><td>"+date(x.createdAt)+"</td><td>"+(x.direction==="out"?"−":"+")+cash(x.amount)+"</td><td>"+cash(x.fee||0)+"</td><td>Sample</td></tr>").join("")+"</tbody></table></div>":"<div class='empty'><b>No wallet activity</b></div>")+"</section><aside class='panel fee-card'><small class='section-kicker'>SAMPLE DEPOSIT & WITHDRAWAL FEES</small><h2>Illustrative flat bands</h2><p>₦15 up to ₦10,000 · ₦30 up to ₦50,000 · ₦50 up to ₦100,000 · ₦100 above.</p><p>Internal Ajo debits and payout credits have no additional fee in this prototype.</p></aside></div>";
}
function communityPage(){
 const f=S.communityFilters,offers=S.data.publicOffers||[];
 const min=Number(f.min)||0,max=Number(f.max)||Infinity,seats=Number(f.seats)||0,turns=Number(f.turns)||0;
 let filtered=offers.filter(o=>(!f.q||((o.name+" "+o.description+" "+o.author).toLowerCase().includes(f.q.toLowerCase())))&&o.amount>=min&&o.amount<=max&&(!f.frequency||o.frequency===f.frequency)&&(!seats||o.capacity>=seats)&&(!turns||o.duration>=turns));
 filtered.sort((a,b)=>f.sort==="amount"?a.amount-b.amount:Date.parse(b.createdAt)-Date.parse(a.createdAt));
 const cards=filtered.map(o=>"<article class='offer-card'><div class='offer-top'><span class='cycle-tag'>"+esc(o.frequency)+" · "+o.duration+" turns</span><span class='offer-author'>"+esc(o.author)+"</span></div><h2>"+esc(o.name)+"</h2><strong class='offer-amount'>"+cash(o.amount)+" <small>/ member / "+esc(o.frequency.toLowerCase())+"</small></strong><p>"+esc(o.description||"Let's agree the details together.")+"</p><div class='offer-meta'><span>"+Math.max(0,o.capacity-o.interestCount-(o.isOwner?1:0))+" seats open</span><span>Due "+date(o.nextDueAt)+"</span><span>"+o.duration+" contributions</span></div><div class='social-actions'><button class='social-interest' data-action='offer-interest' data-id='"+esc(o.id)+"' "+(o.isOwner||o.formedGroupId?"disabled":"")+">"+(o.interested?"✓ Interested · "+o.interestCount:"I’m interested · "+o.interestCount)+"</button><button class='social-comment' data-action='offer-comments' data-id='"+esc(o.id)+"' aria-label='View "+(o.comments||[]).length+" comments'><span class='comment-glyph' aria-hidden='true'></span><span>"+(o.comments||[]).length+"</span></button><button class='social-share' data-action='share-offer' data-id='"+esc(o.id)+"'>Share</button><button class='social-more' data-action='offer-more' data-id='"+esc(o.id)+"' aria-label='More post actions'>⋯</button></div></article>").join("");
 return "<div class='page-head'><div><small class='section-kicker'>PUBLIC AJO BOARD</small><h1>Find your Ajo people</h1><p>Browse offers, ask questions, or join a group that fits your contribution.</p></div><button class='btn btn-primary' data-action='new-offer'>Post an offer</button></div><form data-form='community-filter' class='panel community-filters'><label>Search offers<input name='q' value='"+esc(f.q)+"' placeholder='Name, terms or member'></label><label>Minimum amount<input name='min' type='number' min='0' value='"+esc(f.min)+"' placeholder='₦5,000'></label><label>Maximum amount<input name='max' type='number' min='0' value='"+esc(f.max)+"' placeholder='₦25,000'></label><label>Frequency<select name='frequency'><option value=''>Any</option><option " +(f.frequency==="Weekly"?"selected":"")+">Weekly</option><option "+(f.frequency==="Monthly"?"selected":"")+">Monthly</option></select></label><label>Minimum seats<input name='seats' type='number' min='0' value='"+esc(f.seats)+"' placeholder='Any'></label><label>Minimum turns<input name='turns' type='number' min='0' value='"+esc(f.turns)+"' placeholder='Any'></label><label>Sort<select name='sort'><option value='newest' "+(f.sort!=="amount"?"selected":"")+">Newest</option><option value='amount' "+(f.sort==="amount"?"selected":"")+">Lowest amount</option></select></label><button class='btn btn-outline'>Search</button></form><div class='offer-grid'>"+(cards||"<div class='empty'><b>No offers match those filters</b><p>Adjust the amount range or clear your search.</p></div>")+"</div>";
}
function offerDetails(id){
 const o=(S.data.publicOffers||[]).find(x=>x.id===id);if(!o)return;
 const open=Math.max(0,o.capacity-o.interestCount-(o.isOwner?1:0));
 openModal(modalHead("AJO OFFER DETAILS",esc(o.name))+"<p class='modal-lead'>Posted by "+esc(o.author)+" · "+esc(o.frequency)+" Ajo</p><div class='offer-detail-grid'><div><small>CONTRIBUTION PER MEMBER</small><b>"+cash(o.amount)+"</b></div><div><small>CONTRIBUTION SCHEDULE</small><b>"+esc(o.frequency)+" · "+o.duration+" turns</b></div><div><small>PLANNED GROUP SIZE</small><b>"+o.capacity+" members · "+open+" seats open</b></div><div><small>ESTIMATED POT IF FULL</small><b>"+cash(o.amount*o.capacity)+" per payout turn</b></div><div><small>PROPOSED FIRST DUE DATE</small><b>"+date(o.nextDueAt)+"</b></div><div><small>INTERESTED MEMBERS</small><b>"+o.interestCount+" of "+o.capacity+" seats</b></div></div><p class='offer-detail-description'>"+esc(o.description||"No extra description was provided.")+"</p><div class='modal-note'>This is a public proposal, not a formed group or confirmed payment schedule. The payout estimate assumes all planned seats are filled; discuss and confirm terms before joining.</div><div class='modal-actions'>"+(o.isOwner&&!o.formedGroupId?"<button class='btn btn-outline' data-action='close-modal'>Close</button><button class='btn btn-primary' data-action='form-offer-group' data-id='"+esc(o.id)+"'>Form private Ajo group</button>":!o.isOwner&&!o.formedGroupId?"<button class='btn btn-quiet' data-action='close-modal'>Close</button><button class='btn btn-primary' data-action='offer-interest' data-id='"+esc(o.id)+"'>"+(o.interested?"Withdraw interest":"I’m interested")+"</button>":"<button class='btn btn-primary' data-action='close-modal'>Close</button>")+"</div>");
}
function trustPage(){
 const v=S.data.verification||{},r=S.data.rating||{},d=S.data.disputes||[],guarantors=S.data.guarantorRequests||[],candidates=S.data.guarantorCandidates||[];
 const groups=S.data.groups||[],firstGroup=groups[0],groupOptions=groups.map(g=>"<option value='"+esc(g.id)+"'>"+esc(g.name)+"</option>").join("");
 const memberOptions=group=>group?(group.members||[]).filter(m=>m.userId!==S.data.user.id).map(m=>"<option value='"+esc(m.userId)+"'>"+esc(m.name)+"</option>").join(""):"";
 const step=(kind,title,status)=>"<div class='verify-row'><span class='"+(status.includes("verified")?"done":"")+"'>"+(status.includes("verified")?"✓":"○")+"</span><div><b>"+title+" <i>MOCK</i></b><small>"+(status.includes("verified")?"Sample status only":"Not started")+"</small></div><button class='text-link' data-action='mock-verify' data-kind='"+kind+"'>"+(status.includes("verified")?"Refresh sample":"Show sample status")+"</button></div>";
 return "<div class='page-head'><div><small class='section-kicker'>TRUST & SAFETY</small><h1>Verification and reputation</h1><p>Identity checks, guarantor commitments, and participation history are separate.</p></div></div><div class='notice'><span>Prototype only: no real identity documents or financial information are collected, and no guarantor obligation is created.</span></div><div class='trust-layout'><section class='panel'><div class='panel-head'><div><small class='section-kicker'>MOCK KYC JOURNEY</small><h2>Sample identity status</h2></div></div><p class='modal-note'>Do not enter real BVN/NIN numbers or upload documents. These buttons only change fictional statuses.</p>"+step("email","Email",v.email)+step("bvn","BVN status",v.bvn)+step("nin","NIN status",v.nin)+"</section><section class='panel rating-card'><small class='section-kicker'>AJO PARTICIPATION HISTORY</small><h2>"+(r.eligible?"★ "+Number(r.score).toFixed(1)+" / 5":"Not rated yet")+"</h2><p>"+esc(r.note)+"</p>"+(r.eligible?"<div class='rating-evidence'>"+r.onTimeCount+" of "+r.totalCount+" recorded contributions were on time · based on sample activity.</div>":"<div class='rating-evidence'>"+r.completedActivity+" / 20 completed contribution records</div>")+"<small>Participation signal only; not a credit score, guarantee, or identity check.</small></section></div><section class='panel guarantor-panel'><div class='panel-head'><div><small class='section-kicker'>SAMPLE GUARANTOR FLOW</small><h2>Defined commitment · explicit acceptance</h2></div><small>Mock only</small></div><p>A guarantor is a separate person who reviews a specific member, group, maximum amount, and duration. The illustrated trigger is a missed contribution after review; no automatic debit is simulated. This demo does not create a legal promise, verify identity, contact anyone, or collect money.</p>"+(firstGroup?"<form data-form='guarantor-request' class='inline-form' novalidate><label>Ajo group<select name='groupId' required>"+groupOptions+"</select></label><label>Sample guarantor account<select name='guarantorUserId' required><option value=''>Choose a demo account</option>"+candidates.map(x=>"<option value='"+esc(x.id)+"'>"+esc(x.name)+" · sample invitee</option>").join("")+"</select></label><label>Maximum sample commitment (₦)<input type='number' name='maxLiability' min='500' max='"+(Number(firstGroup.contributionAmount)*Number(firstGroup.capacity))+"' step='500' value='"+esc(firstGroup.contributionAmount)+"' required></label><label class='consent-label'><input type='checkbox' name='termsAcknowledged' required> I understand this is a simulation, not a legal guarantee.</label><button class='btn btn-primary'>Send sample request</button></form>":"<p>Join or create an Ajo group to preview a sample guarantor request.</p>")+"<div class='guarantor-records'>"+(guarantors.length?guarantors.map(g=>"<article class='guarantor-record'><div><b>"+esc(g.incoming?g.memberName:g.guarantorName)+" · "+esc(g.groupName)+"</b><small>Maximum sample amount: "+cash(g.maxLiability)+" · "+esc(g.durationLabel)+" · "+esc(g.status.replaceAll("_"," "))+"</small><small>Trigger illustration: missed contribution followed by review; no automatic debit. "+(g.incoming?"You are being asked to review this sample request.":"Sample request sent to "+esc(g.guarantorName)+".")+"</small></div>"+(g.incoming&&g.status==="pending_demo"?"<div class='guarantor-actions'><button class='btn btn-outline btn-small' data-action='guarantor-response' data-id='"+esc(g.id)+"' data-decision='declined'>Decline</button><button class='btn btn-primary btn-small' data-action='guarantor-response' data-id='"+esc(g.id)+"' data-decision='accepted'>Accept sample</button></div>":"")+"</article>").join(""):"<p class='empty-inline'>No sample requests yet. Send one, then sign out and choose the invited sample account to review it.</p>")+"</div><div class='modal-note'>Acceptance here is only a UI demonstration. No enforceable guarantee or recovery is created.</div></section><section class='panel dispute-panel'><div class='panel-head'><div><small class='section-kicker'>DISPUTE EVIDENCE</small><h2>Report a missed contribution</h2></div></div><p>Creates a sample review record. KYC status cannot guarantee payment or recovery.</p>"+(firstGroup?"<form data-form='dispute' class='inline-form'><label>Ajo group<select name='groupId' data-dispute-group required>"+groupOptions+"</select></label><label>Member<select name='reportedUserId' data-dispute-member required>"+memberOptions(firstGroup)+"</select></label><label>Evidence note<input name='evidenceNote' maxlength='240' placeholder='Sample note only'></label><button class='btn btn-outline'>Create sample report</button></form>":"<p>Create or join an Ajo group before opening a sample report.</p>")+(d.length?"<div class='audit-row'><div><b>"+d.length+" sample dispute(s) on your account</b><small>Demo review only · no external tracing</small></div></div>":"")+"</section>";
}
function toggle(name,title,detail,on){return"<label class='toggle-row'><span><b>"+title+"</b><small>"+detail+"</small></span><input type='checkbox' name='"+name+"' "+(on?"checked":"")+"><i></i></label>";}
function settingsPage(){
 const u=S.data.user,p=u.preferences||{};
 const storageNote=S.data.storageMode==="supabase"?"Data uses a development store. Use sample data only.":"Data is held in local memory and resets when the server restarts.";
 return "<div class='page-head'><div><small class='section-kicker'>ACCOUNT</small><h1>Settings</h1><p>Manage your account preferences.</p></div></div><form data-form='settings' class='settings-form'><section class='panel settings-card'><div class='panel-head'><div><small class='section-kicker'>PROFILE</small><h2>Account details</h2></div></div><div class='readonly-email'><div><b>Member name</b><small>"+esc(u.name)+"</small></div></div><div class='readonly-email'><div><b>Sign-in email</b><small>"+esc(u.email)+"</small></div></div></section><section class='privacy-box'><div><strong>Prototype status</strong><p>"+esc(storageNote)+" Wallet balances and all Ajo transfers are simulated. No real funds are held or paid out.</p><button type='button' class='text-link' data-action='help'>How the prototype works</button></div></section><div class='settings-actions'><button class='btn btn-quiet' type='button' data-action='logout'>Sign out</button></div></form>";
}
function content(){switch(S.view){case"groups":return groupsPage();case"chats":return chatsPage();case"wallet":return walletPage();case"community":return communityPage();case"trust":return trustPage();case"activity":return activityPage();case"settings":return settingsPage();default:return overview();}}
function renderApp(){
 if(!S.data)return;theme(S.data.user.preferences.theme);
 workspace.innerHTML="<div class='app-shell'><aside class='sidebar'><button class='brand app-brand' data-action='overview'><span class='brand-mark'><b>TA</b><i></i></span><span class='brand-word'><strong>Trust Ajo</strong><small>Ajo wallet & community</small></span></button><div class='workspace-switch'><span>"+esc(initials(S.data.user.name))+"</span><div><strong>"+esc(S.data.user.name)+"</strong><small>Member account</small></div></div><small class='side-caption'>YOUR TRUST AJO</small><nav>"+nav("overview","Overview")+nav("wallet","Wallet")+nav("community","Community")+nav("groups","Ajo groups")+nav("chats","Group chats")+nav("trust","Trust & KYC")+nav("activity","Activity records")+nav("settings","Settings")+"</nav><div class='side-bottom'><div class='side-help'><span>?</span><strong>Sample prototype</strong><p>Wallet, transfers and identity statuses use fictional data. No money moves.</p><button class='text-link' data-action='help'>How it works</button></div><div class='side-account'><div><strong>"+esc(S.data.user.name)+"</strong><small>"+esc(S.data.user.email)+"</small></div></div></div></aside><section class='main-pane'><header class='topbar'><div class='top-left'><button class='mobile-menu' data-action='sidebar-toggle' aria-label='Open navigation'>Menu</button><span>Trust Ajo <i>/</i> <strong>"+heading()+"</strong></span></div></header><main class='app-content'>"+content()+"</main><footer class='app-footer'><span>Trust Ajo · prototype</span><span>Sample wallet only · no real money moves.</span></footer></section></div>";
 workspace.querySelectorAll(".table-scroll table").forEach(table=>{const labels=[...table.querySelectorAll("thead th")].map(th=>th.textContent.trim());table.querySelectorAll("tbody tr").forEach(row=>[...row.cells].forEach((cell,index)=>{if(labels[index])cell.dataset.label=labels[index];}));});
 if(S.view==="chats"){const thread=workspace.querySelector(".group-chat-thread");if(thread){thread.scrollTop=Number.isFinite(S.chatScrollRestore)?S.chatScrollRestore:thread.scrollHeight;S.chatScrollRestore=null;}}
}
function modalHead(k,t){return"<div class='modal-head'><div><small class='section-kicker'>"+k+"</small><h2>"+t+"</h2></div><button class='modal-close' data-action='close-modal'>×</button></div>";}
function openModal(s){modal.innerHTML="<div class='modal-backdrop'><section class='modal-card' role='dialog' aria-modal='true' aria-label='Trust Ajo dialog'>"+s+"</section></div>";const first=modal.querySelector("input:not([type=hidden]),textarea,select,button,[tabindex='0']");if(first)requestAnimationFrame(()=>first.focus());}
function closeModal(){modal.innerHTML="";}
function dateInputValue(date){return new Date(date).toISOString().slice(0,10);}
function firstDueDateDefault(frequency){const d=new Date();d.setUTCHours(12,0,0,0);if(frequency==="Monthly"){const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(Math.min(day,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));}else d.setUTCDate(d.getUTCDate()+7);return dateInputValue(d);}
function groupModal(){const minDate=dateInputValue(new Date());openModal(modalHead("CREATE AJO GROUP","Set the group terms.")+"<p class='modal-lead'>Choose contribution amount, frequency, first due date, and member capacity. The group gets a private chat after it is created.</p><form data-form='create-group' class='modal-form'><label>Ajo group name<input name='name' required minlength='3' maxlength='60' placeholder='e.g. Market group'></label><div class='form-pair'><label>Contribution amount (NGN)<input type='number' min='1000' max='1000000' step='100' name='contributionAmount' required placeholder='25000'></label><label>Frequency<select name='frequency'><option>Weekly</option><option>Monthly</option></select></label></div><label>First contribution due<input type='date' name='firstDueDate' min='"+minDate+"' value='"+firstDueDateDefault("Weekly")+"' required></label><label>Member capacity<input type='number' min='3' max='20' name='capacity' value='5' required></label><div class='modal-note'>Sample data only. No money is collected or paid out.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' type='submit'>Create Ajo group</button></div></form>");}
function offerModal(){openModal(modalHead("COMMUNITY BOARD","Post an Ajo offer")+"<p class='modal-lead'>Other members can search your amount range, ask questions, and express interest. You choose when to form a private Ajo group.</p><form data-form='offer-create' class='modal-form'><label>Offer title<input name='name' required minlength='4' maxlength='70' placeholder='e.g. Stock-up Ajo'></label><div class='form-pair'><label>Contribution per member (₦)<input name='amount' type='number' min='1000' max='1000000' required value='5000'></label><label>Frequency<select name='frequency'><option>Weekly</option><option>Monthly</option></select></label></div><div class='form-pair'><label>Number of turns<input name='duration' type='number' min='2' max='52' required value='5'></label><label>Total group seats<input name='capacity' type='number' min='3' max='20' required value='5'></label></div><label>What should people know?<input name='description' maxlength='240' placeholder='Share a short note about the proposed terms'></label><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary'>Post offer</button></div></form>");}
function offerComments(id){const o=(S.data.publicOffers||[]).find(item=>item.id===id);if(!o)return;const comments=(o.comments||[]).map(c=>"<article class='comment-item'><b>"+esc(c.name)+"</b><p>"+esc(c.text)+"</p><small>"+date(c.createdAt)+"</small></article>").join("");openModal(modalHead("PUBLIC DISCUSSION",esc(o.name))+"<div class='comment-thread' aria-live='polite'>"+(comments||"<p class='muted'>No comments yet. Start the conversation.</p>")+"</div><form data-form='offer-comment' class='comment-composer'><input type='hidden' name='offerId' value='"+esc(o.id)+"'><textarea name='text' maxlength='240' required rows='3' placeholder='Write a comment or ask about the terms'></textarea><button class='btn btn-primary'>Post comment</button></form>");}
function walletMoveModal(kind){const deposit=kind==="deposit";openModal(modalHead("SAMPLE WALLET",deposit?"Add sample funds":"Withdraw sample funds")+"<p class='modal-lead'>This is a simulated transaction. The illustrative service fee is shown on the wallet page.</p><form data-form='wallet-move' class='modal-form'><input type='hidden' name='kind' value='"+kind+"'><label>Amount (₦)<input type='number' name='amount' min='500' max='1000000' step='100' value='5000' required></label><div class='modal-note'>No bank, debit card or payment provider is connected. No funds will move.</div><div class='modal-actions'><button type='button' class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary'>"+(deposit?"Add sample funds":"Confirm sample withdrawal")+"</button></div></form>");}
function details(id){
 const g=(S.data.groups||[]).find(x=>x.id===id);if(!g)return;
 const orderedMembers=(g.payoutOrder||[]).map(name=>(g.members||[]).find(m=>m.name===name)).filter(Boolean);
 const members=orderedMembers.map((m,i)=>"<div class='member-line'><div><b>"+esc(m.name)+(m.userId===S.data.user.id?" (you)":"")+"</b><small>"+esc(m.role)+"</small></div><span>"+(i+1)+"</span></div>").join("");
 const expiryLabel=g.joinCodeExpiresAt?new Intl.DateTimeFormat("en-NG",{hour:"numeric",minute:"2-digit"}).format(new Date(g.joinCodeExpiresAt)):"in 10 minutes";
 const invite=g.joinCode?"<div class='invite-code-block'><div><b>Invite a member</b><small>Expires at "+esc(expiryLabel)+" · renews automatically after 10 minutes.</small></div><code>"+esc(g.joinCode)+"</code><button class='btn btn-outline btn-small' data-action='copy-code' data-code='"+esc(g.joinCode)+"'>Copy</button><button class='btn btn-outline btn-small' data-action='rotate-code' data-id='"+esc(g.id)+"'>Rotate code</button></div>":"";
 const pending=(g.swapRequests||[]).filter(x=>x.status==="pending"&&x.to===S.data.user.name).map(x=>"<div class='swap-row'><span>"+esc(x.from)+" requests to swap payout turns with you.</span><button class='btn btn-outline btn-small' data-action='accept-swap' data-group='"+esc(g.id)+"' data-from='"+esc(x.from)+"' data-to='"+esc(x.to)+"'>Accept swap</button></div>").join("");
 const swapOptions=(g.members||[]).filter(m=>m.userId!==S.data.user.id).map(m=>"<option value='"+esc(m.name)+"'>"+esc(m.name)+"</option>").join("");
 const canContribute=g.status!=="ended"&&g.myContributionStatus!=="recorded"&&dueNow(g.nextDueAt)&&g.memberCount===g.capacity;
 const choice=(g.endDecisionStatus&&g.endDecisionStatus!=="active")?"<section class='end-choice'><b>Rotation complete · "+(g.completedRotations||0)+" full Ajo rotations</b><p>Status: "+esc(g.endDecisionStatus.replaceAll("_"," "))+" · Your choice: "+esc((g.memberEndChoices||{})[S.data.user.id]||"not submitted")+"</p>"+(g.status==="ended"?"<p>This Ajo group has ended.</p>":g.status==="recruiting"?"<p>The organizer is finding replacement members. Choices will reopen when the group is ready.</p>":(g.memberEndChoices||{})[S.data.user.id]?"<p>Your choice is recorded. Waiting for the other members.</p>":"<div class='modal-actions'><button class='btn btn-outline btn-small' data-action='end-choice' data-id='"+esc(g.id)+"' data-choice='continue'>Continue</button><button class='btn btn-outline btn-small' data-action='end-choice' data-id='"+esc(g.id)+"' data-choice='replace'>Find replacements</button><button class='btn btn-quiet btn-small' data-action='end-choice' data-id='"+esc(g.id)+"' data-choice='leave'>Leave after this rotation</button></div>")+"</section>":"";
 openModal(modalHead("PRIVATE AJO GROUP",esc(g.name))+"<p class='modal-lead'>"+g.frequency+" · "+cash(g.contributionAmount)+" per member / cycle</p><div class='detail-progress'><b>"+g.paidThisCycle+" / "+g.memberCount+" contributions recorded</b><span>Next due "+date(g.nextDueAt)+"</span></div><div class='progress'><span style='width:"+Math.round(g.paidThisCycle/Math.max(1,g.memberCount)*100)+"%'></span></div><div class='member-list-head'><b>Payout order</b><span>Agreed schedule</span></div><div class='member-list'>"+members+"</div>"+invite+(canContribute?"<div class='modal-actions'><button class='btn btn-primary' data-action='wallet-contribute' data-id='"+esc(g.id)+"'>Contribute from wallet</button></div>":"")+"<section class='panel mini-panel group-chat-link'><div><small class='section-kicker'>PRIVATE GROUP CHAT</small><b>Discuss terms and updates with these members.</b></div><button class='btn btn-outline' data-action='group-chat-open' data-id='"+esc(g.id)+"'>Open group chat</button></section><section class='panel mini-panel'><div class='panel-head'><div><small class='section-kicker'>PAYOUT SWAP</small><h2>Request a turn swap</h2></div></div><p>Swap takes effect only after the other member accepts.</p><form data-form='swap-request' class='inline-form'><input type='hidden' name='groupId' value='"+esc(g.id)+"'><select name='to' required>"+swapOptions+"</select><button class='btn btn-outline btn-small'>Request swap</button></form>"+pending+"</section>"+choice+"<div class='modal-note'>All balances, contributions and payouts are sample records. No real money moves.</div><div class='modal-actions'><button class='btn btn-primary' data-action='close-modal'>Close</button></div>");
}
function helpModal(){openModal(modalHead("PROTOTYPE GUIDE","Trust Ajo sample mode")+"<div class='guide'><p><b>Find an Ajo group.</b> Search public offers by contribution range, frequency, seats, and duration. Discuss terms on the post, then form a private group with its own member chat.</p><p><b>Use the wallet screens.</b> Deposits, withdrawals, contribution debits, payout credits, and fee examples are simulated with fictional balances. No real money moves.</p><p><b>Wallet architecture planned for production.</b> A selected, appropriately authorised payment partner would hold or move funds. Trust Ajo would map each member to a separate partner reference, record verified partner events in an append-only ledger, deduplicate retries, and reconcile records. The partner and legal review must confirm the permitted model before live funds are handled.</p><p><b>Protect member trust.</b> A guarantor must review a specific capped commitment and accept it themselves; this demo only simulates that flow and creates no enforceable promise. Participation ratings require 20 completed contribution records and are not a credit score. Mock identity and dispute statuses do not trace or recover funds.</p><p><b>Stay in prototype mode.</b> Do not enter real identity numbers, card details, or bank information.</p></div><div class='modal-actions'><button class='btn btn-primary' data-action='close-modal'>Close</button></div>");}
async function runAction(name,el){
 if(S.busy)return;
 try{
  if(name==="show-login"){showAuth("login");return;}if(name==="show-signup"){showAuth("signup");return;}if(name==="home"){S.page="landing";page("landing");return;}if(name==="login"){showAuth("login");return;}if(name==="signup"){showAuth("signup");return;}
  if(name==="sample-workspace"){if(S.supabaseAuth){toast("Sign in with your account to continue.",true);return;}openModal(modalHead("SAMPLE SCENARIOS","Choose a demo account")+"<p class='modal-lead'>Each scenario loads fictional members and group activity for a different walkthrough.</p><div class='scenario-list'><button class='scenario-option' data-action='load-scenario' data-scenario='member'>New member · wallet and one Ajo group</button><button class='scenario-option' data-action='load-scenario' data-scenario='multiple'>Active member · multiple Ajo groups</button><button class='scenario-option' data-action='load-scenario' data-scenario='organizer'>Organizer · community post and interested members</button><button class='scenario-option' data-action='load-scenario' data-scenario='attention'>Member · missed contribution and dispute flow</button></div><div class='modal-note'>Sample only. No real payments, identity checks, or guarantor commitments occur.</div>");return;}
  if(name==="load-scenario"){S.busy=true;await api("/api/auth/demo","POST",{scenario:el.dataset.scenario});S.data=await api("/api/bootstrap");S.view="overview";S.page="app";closeModal();renderApp();page("app");toast("Sample scenario loaded.");return;}
  if(name==="new-group"){groupModal();return;}if(name==="new-offer"){offerModal();return;}if(name==="wallet-deposit"){walletMoveModal("deposit");return;}if(name==="wallet-withdraw"){walletMoveModal("withdraw");return;}if(name==="dismiss-join-preview"){S.joinPreview=null;renderApp();return;}if(name==="confirm-join"){if(!S.joinPreview||S.joinPreview.conflict)throw new Error("Review a valid Ajo invitation before joining.");const joining=S.joinPreview.group;S.busy=true;S.data=await api("/api/groups/join","POST",{joinCode:S.joinPreview.joinCode});S.joinPreview=null;renderApp();toast("You joined "+joining.name+".");return;}if(name==="rotate-code"){openModal(modalHead("ROTATE INVITE","Replace this invite code?")+"<p class='modal-lead'>The old code will stop working immediately.</p><div class='modal-actions'><button class='btn btn-quiet' data-action='close-modal'>Cancel</button><button class='btn btn-primary' data-action='rotate-confirm' data-id='"+esc(el.dataset.id)+"'>Replace code</button></div>");return;}if(name==="rotate-confirm"){const groupId=el.dataset.id;S.busy=true;S.data=await api("/api/groups/invite/rotate","POST",{groupId});renderApp();details(groupId);const rotated=S.data.groups.find(g=>g.id===groupId);toast(rotated?"New invite code: "+rotated.joinCode:"Invite code changed.");return;}if(name==="details"){details(el.dataset.id);return;}
  if(name==="offer-interest"){const detailOpen=Boolean(modal.querySelector(".offer-detail-grid")),offerId=el.dataset.id;S.busy=true;S.data=await api("/api/community/offers/interest","POST",{offerId});renderApp();if(detailOpen)offerDetails(offerId);toast("Your interest has been updated.");return;}
  if(name==="offer-comments"){offerComments(el.dataset.id);return;}
  if(name==="offer-more"){offerDetails(el.dataset.id);return;}
  if(name==="group-chat-open"){S.chatGroupId=el.dataset.id;S.view="chats";closeModal();renderApp();return;}
  if(name==="select-chat-group"){S.chatGroupId=el.dataset.id;renderApp();return;}
  if(name==="share-offer"){const o=(S.data.publicOffers||[]).find(x=>x.id===el.dataset.id);if(!o)return;const shareUrl=new URL(location.origin+"/");shareUrl.searchParams.set("post",o.id);try{if(navigator.share){await navigator.share({title:o.name,text:cash(o.amount)+" · "+o.frequency.toLowerCase()+" Ajo · "+o.duration+" turns",url:shareUrl.href});}else{await navigator.clipboard.writeText(shareUrl.href);toast("Offer link copied.");}}catch(e){if(e.name==="AbortError")return;openModal(modalHead("SHARE AJO OFFER","Copy this offer link")+"<label class='copy-field'>Share link<input readonly value='"+esc(shareUrl.href)+"'></label><div class='modal-actions'><button class='btn btn-primary' data-action='close-modal'>Done</button></div>");}return;}
  if(name==="form-offer-group"){S.busy=true;S.data=await api("/api/community/offers/form-group","POST",{offerId:el.dataset.id});closeModal();S.view="groups";renderApp();toast("Private Ajo group formed with interested members.");return;}
  if(name==="accept-swap"){S.busy=true;S.data=await api("/api/groups/swap","POST",{groupId:el.dataset.group,from:el.dataset.from,to:el.dataset.to,accept:true});renderApp();details(el.dataset.group);toast("Payout turns swapped by agreement.");return;}
  if(name==="end-choice"){S.busy=true;S.data=await api("/api/groups/end-choice","POST",{groupId:el.dataset.id,choice:el.dataset.choice});renderApp();details(el.dataset.id);toast("Your choice was recorded.");return;}
  if(name==="wallet-contribute"){S.busy=true;const groupId=el.dataset.id;S.data=await api("/api/groups/contribute","POST",{groupId});renderApp();details(groupId);toast("Sample contribution debited from your wallet.");return;}
  if(name==="mock-verify"){S.busy=true;S.data=await api("/api/verification/demo","POST",{kind:el.dataset.kind});renderApp();toast("Sample verification status updated. No identity provider was contacted.");return;}
  if(name==="activity-clear"){S.activityFilters={q:"",category:"",direction:"",status:"",from:"",to:"",min:"",max:""};renderApp();return;}
  if(name==="guarantor-response"){S.busy=true;S.data=await api("/api/guarantors/demo/respond","POST",{requestId:el.dataset.id,decision:el.dataset.decision});renderApp();toast(el.dataset.decision==="accepted"?"Sample request accepted. No legal commitment was created.":"Sample request declined.");return;}
  if(name==="logout"){if(S.authClient)await S.authClient.auth.signOut({scope:"local"});else await api("/api/auth/logout","POST",{});S.data=null;S.view="overview";S.page="landing";page("landing");return;}
  if(name==="help"){helpModal();return;}if(name==="close-modal"){closeModal();return;}if(name==="toast-close"){toastBox.innerHTML="";return;}
  if(name==="copy-code"){try{await navigator.clipboard.writeText(el.dataset.code);}catch(e){toast("Select and copy the invite code: "+el.dataset.code,true);return;}toast("Invite code copied. Share it privately with your Ajo group.");return;}
  if(name==="refresh"){S.data=await api("/api/bootstrap");renderApp();toast("Contribution records refreshed.");return;}if(name==="overview"){S.view="overview";renderApp();return;}
  if(name==="mobile-menu"){const menu=document.querySelector(".landing-links"),open=menu.classList.toggle("menu-open");el.setAttribute("aria-expanded",String(open));return;}if(name==="sidebar-toggle"){const sidebar=document.querySelector(".sidebar"),open=sidebar.classList.toggle("sidebar-open");el.setAttribute("aria-expanded",String(open));el.setAttribute("aria-label",open?"Close navigation":"Open navigation");return;}
 }catch(e){toast(e.message||"Something went wrong.",true);}finally{S.busy=false;}
}document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();document.querySelector(".sidebar.sidebar-open")?.classList.remove("sidebar-open");document.querySelector(".landing-links.menu-open")?.classList.remove("menu-open");}});
document.addEventListener("click",e=>{
 const side=document.querySelector(".sidebar.sidebar-open");if(side&&!e.target.closest(".sidebar")&&!e.target.closest("[data-action=sidebar-toggle]"))side.classList.remove("sidebar-open");const menu=document.querySelector(".landing-links.menu-open");if(menu&&!e.target.closest(".landing-links")&&!e.target.closest("[data-action=mobile-menu]"))menu.classList.remove("menu-open");
 if(e.target.classList.contains("modal-backdrop")){closeModal();return;}
 const v=e.target.closest("[data-view]");if(v){S.view=v.dataset.view;renderApp();return;}
 const t=e.target.closest("[data-theme-choice]");if(t){const select=document.getElementById("theme-select");if(select){select.value=t.dataset.themeChoice;theme(select.value);document.querySelectorAll("[data-theme-choice]").forEach(x=>x.classList.toggle("selected",x===t));}return;}
 const b=e.target.closest("[data-action]");if(b)runAction(b.dataset.action,b);
});
document.addEventListener("change",e=>{if(e.target&&e.target.id==="theme-select"){theme(e.target.value);document.querySelectorAll("[data-theme-choice]").forEach(x=>x.classList.toggle("selected",x.dataset.themeChoice===e.target.value));}if(e.target&&e.target.name==="frequency"&&e.target.closest("form[data-form=create-group]")){const due=e.target.form.elements.firstDueDate;if(due)due.value=firstDueDateDefault(e.target.value);}if(e.target&&e.target.matches("[data-dispute-group]")){const group=(S.data.groups||[]).find(g=>g.id===e.target.value),select=e.target.form.elements.reportedUserId;select.innerHTML=group?(group.members||[]).filter(m=>m.userId!==S.data.user.id).map(m=>"<option value='"+esc(m.userId)+"'>"+esc(m.name)+"</option>").join(""):"";}});
document.addEventListener("submit",async e=>{
 const f=e.target.closest("form[data-form]");if(!f)return;e.preventDefault();if(S.busy)return;
 const kind=f.dataset.form,fd=new FormData(f);let body={};fd.forEach((v,k)=>body[k]=v);
 try{
  S.busy=true;
  if(kind==="login"){
   if(S.authClient){const {data,error}=await S.authClient.auth.signInWithPassword({email:body.email,password:body.password});if(error||!data.session)throw new Error("Email or password was not recognized.");}
   else await api("/api/auth/login","POST",body);
   S.authNotice="";S.data=await api("/api/bootstrap");S.view=preferredWorkspaceView();S.page="app";renderApp();page("app");toast("Welcome back.");return;
  }
  if(kind==="register"){
   if(S.authClient){const {data,error}=await S.authClient.auth.signUp({email:body.email,password:body.password,options:{data:{name:body.name,business_name:body.businessName,business_type:body.businessType},emailRedirectTo:location.origin}});if(error)throw new Error(error.message);if(!data.session){S.mode="login";S.authNotice="Check your email to confirm your account, then sign in.";renderAuth();return;}}
   else await api("/api/register","POST",body);
   S.authNotice="";S.data=await api("/api/bootstrap");S.view=preferredWorkspaceView();S.page="app";renderApp();page("app");toast("Your Trust Ajo space is ready.");return;
  }
 if(kind==="create-group"){S.data=await api("/api/groups/create","POST",body);S.page="app";S.view="groups";closeModal();renderApp();const g=S.data.groups.find(x=>x.name===body.name&&x.joinCode);toast(g?"Ajo group created. Invite code: "+g.joinCode:"Your Ajo group is ready.");return;}
   if(kind==="join-group"){const joinCode=String(body.joinCode||"").trim().toUpperCase();const result=await api("/api/groups/invite?code="+encodeURIComponent(joinCode));S.joinPreview={...result,joinCode};S.view="groups";renderApp();return;}
  if(kind==="settings"){body={theme:f.elements.theme.value};S.data=await api("/api/settings","POST",body);theme(S.data.user.preferences.theme);renderApp();toast("Settings saved.");return;}
  if(kind==="wallet-move"){S.data=await api("/api/wallet/move","POST",body);closeModal();renderApp();toast("Sample wallet transaction recorded.");return;}
  if(kind==="community-filter"){S.communityFilters={q:String(body.q||"").trim(),min:String(body.min||""),max:String(body.max||""),frequency:String(body.frequency||""),seats:String(body.seats||""),turns:String(body.turns||""),sort:String(body.sort||"newest")};renderApp();return;}
  if(kind==="activity-filter"){if(body.from&&body.to&&body.from>body.to)throw new Error("The start date must be on or before the end date.");if(body.min&&body.max&&Number(body.min)>Number(body.max))throw new Error("Minimum amount cannot exceed maximum amount.");S.activityFilters={q:String(body.q||"").trim(),category:String(body.category||""),direction:String(body.direction||""),status:String(body.status||""),from:String(body.from||""),to:String(body.to||""),min:String(body.min||""),max:String(body.max||"")};renderApp();return;}
  if(kind==="guarantor-request"){if(!body.groupId||!body.guarantorUserId||!body.termsAcknowledged){openModal(modalHead("GUARANTOR REQUEST","Complete the sample request")+"<p class='modal-lead'>Choose a sample guarantor account and tick the acknowledgement before sending. This is only a prototype simulation.</p><div class='modal-actions'><button class='btn btn-primary' data-action='close-modal'>Review form</button></div>");return;}S.data=await api("/api/guarantors/demo/request","POST",body);renderApp();toast("Sample request sent. Switch to that demo account to review it.");return;}
  if(kind==="offer-create"){S.data=await api("/api/community/offers/create","POST",body);closeModal();S.view="community";renderApp();toast("Your offer is now on the public Ajo board.");return;}
  if(kind==="offer-comment"){const offerId=body.offerId;S.data=await api("/api/community/offers/comment","POST",body);renderApp();offerComments(offerId);toast("Comment added.");return;}
  if(kind==="group-chat"){const groupId=body.groupId,send=f.querySelector(".chat-send");if(send){send.disabled=true;send.textContent="…";}S.data=await api("/api/groups/chat","POST",body);S.chatGroupId=groupId;S.view="chats";renderApp();toast("Message sent to your Ajo group.");return;}
  if(kind==="swap-request"){const groupId=body.groupId;body={groupId,from:S.data.user.name,to:body.to};S.data=await api("/api/groups/swap","POST",body);renderApp();details(groupId);toast("Swap request sent.");return;}
  if(kind==="dispute"){S.data=await api("/api/disputes/demo","POST",body);renderApp();toast("Sample dispute record created.");return;}
 }catch(err){toast(err.message||"Something went wrong.",true);}finally{S.busy=false;if(f.isConnected){const send=f.querySelector(".chat-send");if(send){send.disabled=false;send.textContent="➤";}}}
});
async function start(){const config=await api("/api/config");S.supabaseAuth=Boolean(config.supabaseAuth?.enabled);if(S.supabaseAuth){if(!window.supabase?.createClient)throw new Error("Supabase client could not be loaded.");S.authClient=window.supabase.createClient(config.supabaseAuth.url,config.supabaseAuth.publishableKey);document.querySelectorAll("[data-action='sample-workspace']").forEach(el=>el.hidden=true);}const params=new URLSearchParams(location.search);try{S.data=await api("/api/bootstrap");S.view=preferredWorkspaceView();S.page="app";theme(S.data.user.preferences.theme);renderApp();page("app");}catch(e){S.page="landing";page("landing");}}
start();
setInterval(async()=>{if(!S.data||S.page!=="app"||S.busy||document.hidden)return;const expiring=(S.data.groups||[]).some(g=>g.joinCode&&g.joinCodeExpiresAt&&Date.parse(g.joinCodeExpiresAt)<=Date.now()+15000);if(!expiring)return;const openGroupId=modal.querySelector("[data-action='rotate-code']")?.dataset.id;try{const previous=new Map((S.data.groups||[]).map(g=>[g.id,g.joinCode]));const fresh=await api("/api/bootstrap");const changed=(fresh.groups||[]).some(g=>g.joinCode&&previous.get(g.id)!==g.joinCode);S.data=fresh;renderApp();if(openGroupId)details(openGroupId);if(changed)toast("An expired invite code was automatically replaced.");}catch(e){}},15000);
setInterval(async()=>{if(!S.data||S.page!=="app"||S.view!=="chats"||S.busy||document.hidden)return;const active=(S.data.groups||[]).find(g=>g.id===S.chatGroupId),thread=workspace.querySelector(".group-chat-thread");if(!active||!thread)return;const oldStamp=(S.data.groups||[]).map(g=>[g.id,(g.chat||[]).length,(g.chat||[]).at(-1)?.id]).join("|");try{const fresh=await api("/api/bootstrap"),newStamp=(fresh.groups||[]).map(g=>[g.id,(g.chat||[]).length,(g.chat||[]).at(-1)?.id]).join("|");if(oldStamp!==newStamp){const gap=thread.scrollHeight-thread.scrollTop-thread.clientHeight;S.chatScrollRestore=gap<90?null:thread.scrollTop;S.data=fresh;renderApp();}}catch(e){}},5000);
})(); 
